create table api_definition (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, method varchar(8) not null, updated_at timestamp(6) with time zone, status varchar(16) not null, version varchar(32) not null, category varchar(64), tenant_id varchar(64) not null, name varchar(128) not null, full_json varchar(32768), path varchar(255) not null, primary key (id));
create table data_asset (quality_score integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, security_level varchar(16) not null, status varchar(16) not null, type varchar(32) not null, owner varchar(64) not null, tenant_id varchar(64) not null, name varchar(128) not null, description varchar(512), full_json varchar(32768), primary key (id));
create table datasource (port integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, status varchar(16) not null, type varchar(32) not null, tenant_id varchar(64) not null, database varchar(128), name varchar(128) not null, username varchar(128) not null, host varchar(255) not null, password varchar(255), primary key (id), constraint uk_datasource_tenant_name unique (tenant_id, name));
create table develop_schedule (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, status varchar(16) not null, engine varchar(32) not null, schedule varchar(64) not null, tenant_id varchar(64) not null, file_path varchar(512) not null, dependencies varchar(2048), primary key (id));
create table gateway_api_key (rate_limit integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, status varchar(16) not null, tenant_id varchar(64) not null, api_key varchar(128) not null unique, name varchar(128) not null, route_model varchar(128) not null, secret_hash varchar(128) not null, scope varchar(512), primary key (id), constraint uk_gateway_api_key_tenant_name unique (tenant_id, name));
create table industry_template (install_count integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, status varchar(16) not null, industry varchar(32) not null, version varchar(32) not null, tenant_id varchar(64) not null, author varchar(128), name varchar(128) not null, description varchar(512), full_json varchar(32768), primary key (id));
create table invite_codes (activated_at timestamp(6), created_at timestamp(6), expires_at timestamp(6), id bigint generated by default as identity, tenant_id bigint, activated_by varchar(255), code varchar(255), invited_by varchar(255), note varchar(255), role varchar(255), status varchar(255), primary key (id), constraint idx_invite_code unique (code));
create table knowledge_base (doc_count integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, status varchar(16) not null, tenant_id varchar(64) not null, name varchar(128) not null, chunk_strategy varchar(255), retrieval varchar(255), primary key (id));
create table knowledge_document (chunk_count integer, vector_count integer, file_size bigint, id bigint generated by default as identity, knowledge_base_id bigint not null, updated_at timestamp(6) with time zone, uploaded_at timestamp(6) with time zone not null, status varchar(16) not null, file_type varchar(32), tenant_id varchar(64) not null, storage_path varchar(512), error_message varchar(1024), file_name varchar(255) not null, primary key (id));
create table knowledge_rag_strategy (citation_enabled boolean, score_threshold float(53), topk integer, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, chunk_strategy varchar(32), retrieval_method varchar(32), tenant_id varchar(64) not null unique, reranker_model varchar(128), primary key (id));
create table llm_eval_metric (accuracy float(53), base_lift_pt float(53), hallucination_rate float(53), created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, eval_type varchar(16) not null, model_version varchar(64), tenant_id varchar(64) not null, model_name varchar(128) not null, detail_json varchar(4096), dataset varchar(255), primary key (id));
create table llm_finetune_task (epochs integer, progress integer, finished_at timestamp(6) with time zone, id bigint generated by default as identity, started_at timestamp(6) with time zone, submitted_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone, status varchar(16) not null, gpu_config varchar(64), task_id varchar(64) not null unique, tenant_id varchar(64) not null, base_model varchar(128) not null, model_name varchar(128) not null, log_path varchar(512), training_data varchar(512), error_message varchar(1024), primary key (id));
create table ml_inference_service (desired_replicas integer, latency_ms float(53), qps float(53), replicas integer, deployed_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, status varchar(16) not null, model_version varchar(64) not null, resource_spec varchar(64), tenant_id varchar(64) not null, model_name varchar(128) not null, service_name varchar(128) not null, endpoint varchar(512), primary key (id));
create table ml_model (id bigint generated by default as identity, registered_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone, status varchar(16) not null, algorithm varchar(32) not null, tenant_id varchar(64) not null, train_job_id varchar(64), version varchar(64) not null, name varchar(128) not null, description varchar(512), model_path varchar(512), metrics_json varchar(4096), primary key (id), constraint uk_ml_model_tenant_name_version unique (tenant_id, name, version));
create table project (datasets integer not null, jobs integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, status varchar(16) not null, domain varchar(64) not null, tenant_id varchar(64) not null, name varchar(128) not null, description varchar(512), primary key (id));
create table sec_mask_policy (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, status varchar(16) not null, algorithm varchar(32) not null, strategy varchar(32) not null, tenant_id varchar(64) not null, field_name varchar(128) not null, asset_name varchar(255) not null, primary key (id));
create table standard (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, status varchar(16) not null, type varchar(32) not null, tenant_id varchar(64) not null, name varchar(128) not null, description varchar(512), rule varchar(512), primary key (id));
create table sync_task (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone, status varchar(16) not null, source_type varchar(32) not null, target_type varchar(32) not null, schedule varchar(64), tenant_id varchar(64) not null, name varchar(128) not null, seatunnel_job_id varchar(128), source_table varchar(255), target_table varchar(255), primary key (id));
create table tenants (created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), display_name varchar(255), name varchar(255) not null, namespace varchar(255), quota_profile varchar(255), status varchar(255), primary key (id));
create table user_registrations (approved_at timestamp(6), created_at timestamp(6), id bigint generated by default as identity, tenant_id bigint, approve_note varchar(255), approved_by varchar(255), department varchar(255), email varchar(255), employee_id varchar(255), full_name varchar(255), invite_code varchar(255), role varchar(255), status varchar(255), username varchar(255), primary key (id), constraint idx_reg_username unique (username));
create index idx_develop_schedule_tenant on develop_schedule (tenant_id);
create index idx_develop_schedule_file on develop_schedule (file_path);
create index idx_invite_tenant on invite_codes (tenant_id);
create index idx_reg_tenant on user_registrations (tenant_id);
